const b = msg.payload || {};
const h = String((msg.req.headers || {}).authorization || '');
const sessao = h.replace(/^Bearer\s+/i, '').trim();
const device = String(b.device || '');
const modulo = String(b.module || '');
const acao   = String(b.action || '');

// Lista fechada de propósito: sem ela, o corpo da requisição escolheria o
// tópico, e a rota viraria um publicador MQTT genérico exposto na internet.
const MODULOS = ['camera', 'alarme'];
const ACOES = {
    camera: ['snapshot', 'clear_recordings'],
    alarme: ['on', 'off', 'test'],
};

if (!/^[A-Za-z0-9-]{3,32}$/.test(device) ||
    MODULOS.indexOf(modulo) < 0 ||
    (ACOES[modulo] || []).indexOf(acao) < 0) {
    msg.statusCode = 400;
    msg.payload = { error: 'invalid_command' };
    return [null, msg];
}

// guarda o comando para depois da checagem de posse
msg.cmd = { device: device, module: modulo, body: JSON.stringify(b.args
            ? Object.assign({ action: acao }, b.args)
            : { action: acao }) };
msg.params = [sessao, device];
return [msg, null];

const dono = ((msg.payload && msg.payload[0]) || {}).dono === true;
if (!dono) {
    // Sessao invalida e 'nao e o dono' respondem igual: distinguir
    // revelaria quais device_id existem.
    msg.statusCode = 403;
    msg.payload = { error: 'forbidden' };
    return [null, msg];
}
const c = msg.cmd;
msg.topic = 'devices/' + c.device + '/' + c.module + '/command';
msg.payload = c.body;
msg.qos = 1;
msg.retain = false;
return [msg, null];
